<script setup lang="ts">import { computed } from 'vue'; import { useCoachStore } from '@/stores/coach'; import PageHeading from '@/components/PageHeading.vue'; import ProgressRing from '@/components/ProgressRing.vue'; const store = useCoachStore(); const due = computed(() => store.topics.filter(t => t.nextRevision === 'Today').length); const days = computed(() => { const levels=store.activity.slice(-28).map(day=>Math.min(5,Math.ceil(day.study_minutes/15))); return [...Array(Math.max(0,28-levels.length)).fill(0),...levels] }); const studyMinutes=computed(()=>store.activity.reduce((total,day)=>total+day.study_minutes,0));</script>
<template><div class="page progress-page"><PageHeading eyebrow="YOUR MOMENTUM" title="Progress that compounds" description="Every session sharpens your learning graph and makes tomorrow’s plan more precise." />
  <section class="metric-grid"><div class="metric-card featured"><ProgressRing :value="store.overview?.exam_readiness??store.readiness" label="readiness"/><div><span class="eyebrow">EXAM READINESS</span><h2>{{(store.overview?.exam_readiness??store.readiness)>=70?'On track':'Building mastery'}}</h2><p>Based on your assessed topics</p></div></div><div class="metric-card"><span class="metric-icon">🔥</span><strong>{{store.overview?.streak??0}} days</strong><p>Current streak</p><small>Complete a session to keep it active</small></div><div class="metric-card"><span class="metric-icon">✦</span><strong>{{(store.overview?.xp??0).toLocaleString()}}</strong><p>Total XP</p><small>Earned from completed learning work</small></div><div class="metric-card"><span class="metric-icon">↻</span><strong>{{ due }}</strong><p>Reviews due</p><small>About {{due*5}} minutes</small></div></section>
  <div class="progress-grid"><section class="card"><div class="section-heading"><div><span class="eyebrow">KNOWLEDGE GRAPH</span><h2>Your mastery map</h2></div><button class="text-button">View full graph ↗</button></div><div class="topic-list"><article v-for="topic in store.topics" :key="topic.id"><div class="topic-icon" :class="topic.state">{{ topic.domain.slice(0,2).toUpperCase() }}</div><div class="topic-main"><div><strong>{{ topic.name }}</strong><span>{{ topic.domain }}</span></div><div class="progress-track"><i :class="topic.state" :style="{ width: `${topic.mastery}%` }"/></div></div><strong>{{ topic.mastery }}%</strong><span class="revision">{{ topic.nextRevision }}</span></article></div></section>
  <section class="card activity-card"><span class="eyebrow">STUDY ACTIVITY</span><h2>Last 4 weeks</h2><div class="heatmap" aria-label="Study activity heatmap"><i v-for="(level, i) in days" :key="i" :class="`level-${level}`"/></div><div class="heat-legend"><span>Less</span><i/><i class="level-2"/><i class="level-4"/><i class="level-5"/><span>More</span></div><div class="study-summary"><div><strong>{{Math.floor(studyMinutes/60)}}h {{studyMinutes%60}}m</strong><span>Study time</span></div><div><strong>{{store.activity.length}}</strong><span>Active days</span></div></div></section></div>
</div></template>
